from dataclasses import dataclass, asdict, FrozenInstanceError

@dataclass(frozen=True)
class Colour:
    red: int
    green: int
    blue: int

c = Colour(255, 128, 0)
print(asdict(c))
try:
    c.red = 0
except FrozenInstanceError:
    print("Colour is read-only")

